Here is how to control an RGB LED with clean modular firmware:

```cpp
const int redPin = 9;   // PWM Pin ~9
const int greenPin = 10;// PWM Pin ~10
const int bluePin = 11; // PWM Pin ~11

void setup() {
  pinMode(redPin, OUTPUT);
  pinMode(greenPin, OUTPUT);
  pinMode(bluePin, OUTPUT);
}

void setColor(int red, int green, int blue) {
  analogWrite(redPin, constrain(red, 0, 255));
  analogWrite(greenPin, constrain(green, 0, 255));
  analogWrite(bluePin, constrain(blue, 0, 255));
}

void loop() {
  setColor(255, 0, 0);   // Pure Red
  delay(1000);
  setColor(0, 255, 0);   // Pure Green
  delay(1000);
  setColor(0, 0, 255);   // Pure Blue
  delay(1000);
  setColor(255, 255, 0); // Yellow (Red + Green)
  delay(1000);
}
```

By wrapping `analogWrite()` inside a custom `setColor()` function, your sketch becomes clean and readable!
